"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-research-early-rev1';O.mkdir(exist_ok=True)
SOURCE='reference/RESEARCH.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(1, 'METHOD', 'Historical phase findings are hypothesis/control evidence, not canonical topology or automatic readiness.', 'Standing corrections retire production-frequency gating and phase-number-driven construction; heading/separator units organize the same reviewed scope.', ['CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md']), (37, 'PREFERENCE', 'Scripted learning changes mean/precision; paired forced action changes authored outcome.', 'HQ001 preserves incomplete proof of monotonically increasing autonomous preference: urgency/accessibility also vary. Matched RNG requires same addresses, not seed alone.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (61, 'SATURATION', 'Clipped observed delta can understate potential effect; original scenario needed correction.', 'Universal saturation phrase is too broad: equal passive loss/additive gain can repeat without clipping. Clipping is not physiological tolerance, later TOLERANCE qualifies a separate consumer.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md', 'CAMPAIGN3_TOLERANCE_QUALIFICATION.md']), (77, 'UNBUILT', 'Earlier absence of substitution/habit/affect/Values is historical routing, not negative experimental evidence.', 'Later bounded verdicts supersede only their declared scopes; obsession remains HQ008 debt.', ['CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md', 'CAMPAIGN3_VALUES_QUALIFICATION.md']), (84, 'MATH', 'Exact update equivalence, one-step quantization and address isolation are distinct mathematical contracts.', 'Point error bound does not bound arbitrary compounded cycles; address isolation is not statistical independence. Historical all-primitives-used wording not necessity proof.', ['CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md', 'CAMPAIGN3_LEARN_QUALIFICATION.md']), (115, 'ARCHITECTURE', 'Scenario clipping reflects bounded resource dynamics; no second comparator had yet earned minimality.', 'Phase1 alone cannot prove mean/precision representation necessary; graph identifier lookup is an implementation concern, not authority to unify psychological roles.', ['CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md', 'CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (156, 'COMPARISON-ROUTING', 'Vivarium inspection questions and next-phase proposals are proposed work, not completed cross-project comparisons.', 'Independent expectation can supply substitution; associative transfer untested by Phase1. Historical general mechanism necessity speculation not accepted topology.', ['CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md', 'CAMPAIGN3_SUBSTITUTION_QUALIFICATION.md']), (191, 'PHASE1-SUMMARY', 'Repeated learning and decreasing gain explain contradiction resistance under the stated law.', 'Summary restates earlier claims, not new evidence. Confidence diagnostic not calibration; saturation qualified above; mean/precision not universally irreducible.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md', 'CAMPAIGN3_BELIEF_QUALIFICATION.md']), (218, 'PHASE2-HABIT', 'Symmetric coactivation/row normalization yields the reported half-weight and context-only access in this fixture.', 'Row budget and tagging matter; exact1/2 is not universal degree-only law. Historical first-pass status not current closure.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md', 'CAMPAIGN3_HABIT_QUALIFICATION.md']), (246, 'SUBSTITUTION', 'Availability-only swap leaves fixed activation unchanged; precondition and accessibility filters separate.', 'Zero for an unassociated Priya does not test positive learned proximity. DERIVED limited to this fixture, not all substitution. A lawful two-node graph transfers nonzero activation.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md', 'CAMPAIGN3_SUBSTITUTION_QUALIFICATION.md']), (265, 'AVOIDANCE', 'Forced negative learning reduces read-only probability during clean boundary window; later clipping can reverse trend.', 'Not sampled avoidance or general inhibition redundancy. Preserve fixed scenario clean-window scope and separate control qualification.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md', 'CAMPAIGN3_CONTROL_QUALIFICATION.md']), (285, 'MEMORY', 'Recency/repeated retrieval and selected-only update satisfy historical kernel arithmetic.', 'Current architecture separates selection, publication, presentation and use; old retrieve side effect not authority to collapse them. Missing affect routing superseded only boundedly.', ['CAMPAIGN3_DEFINING_PUBLIC_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md']), (300, 'SOLVER', 'Exact rational Gaussian elimination and row-substochastic beta<1 give unique solution; finite stress tests support implementation.', 'Thirty successful solves do not establish distance from singularity or cost bound. Beta approaching1 yields arbitrarily poor conditioning even in lawful2-node graph. Rational reduction not literal Bareiss.', ['CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md']), (322, 'QUANTIZATION', 'Exact solve then per-entry quantization differs from exact residual closure; first wrong test corrected.', 'One-step bounds do not establish long-run compounded error; largest-remainder exact row mass only under specified normalization.', ['CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md', 'GENERAL_ATTENTION_QUALIFICATION_2026_09_20.md']), (342, 'TAGGING', 'Need exclusion supports chosen experimental separation; self-exclusion and shared budget are explicit graph choices.', 'Zero leakage in unconnected fixture does not prove exclusion universally necessary. Identifier rebranding/deferred lookup not psychological reduction.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md', 'CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md']), (383, 'TRANSFER-QUESTIONS', 'Vivarium availability/accessibility and tagging comparisons are questions, not executed parity proof.', 'Broader no-associative-substitution conclusion is unsupported by zero-connected fixture. Appraisal requirement is bounded absence, not mechanism uniqueness.', ['CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md', 'CAMPAIGN3_ATTACHMENT_QUALIFICATION.md']), (427, 'PHASE2-SUMMARY', 'Separate access, availability, learned evaluation and bounded avoidance remain useful tested distinctions.', 'DERIVED/NOT sufficient phrases retain fixture horizon/query set; do not foreclose learned proximity. Shared-budget ceiling and late quantization retain exact conditions.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md', 'CAMPAIGN3_HISTORY_HQ006_CHECKPOINT.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 1<=u['location']['startLine']<=462:continue
  assert u['location']['endLine']<=462
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(1,463) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
level=F(1,2); levels=[]
for _ in range(20):
 before=max(F(0),level-F(1,10));level=min(F(1),before+F(1,10));levels.append(str(level))
assert set(levels)=={'1/2'}
beta=F(1,2);a0=1/(1-beta*beta);a1=beta*a0
assert a0-beta*a1==1 and a1-beta*a0==0 and a1==F(2,3)
near=F(999,1000);condition=(1+near)/(1-near);assert condition==1999
counterexamples=dict(balancedPassiveAndEffect=dict(start='1/2',passive='-1/10',effect='1/10',afterEachCycle=levels),learnedProximity=dict(W=[[0,1],[1,0]],beta='1/2',base=[1,0],solution=[str(a0),str(a1)],scope='Positive legal association, not unconnected original fixture; no world-availability input or desirability effect inferred.'),conditioning=dict(W=[[0,1],[1,0]],beta=str(near),infinityNormCondition=str(condition),scope='Invertible for beta<1; not uniform numerical/cost margin.'))
v=dict(status='HQ011 EARLY REFERENCE RESEARCH CLAIMS REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,counterexamples=counterexamples,obligations=['RO-C3-001','RO-C3-004','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Seventeen reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Reference RESEARCH463 onward: censoring corrections, salience, interpretation and consolidation.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=905+len(rows),freshBehavioralTests=0,freshArithmeticCounterexamples=3,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
